    fn reward_extension_preserves_native_npc_legacy_bindings() -> Result<(), String> {
        let loaded = super::super::loader::load_embedded_quest_state("content-1")
            .map_err(|e| format!("{e:?}"))?;
        assert!(
            !loaded.catalogue().npc_legacy.is_empty(),
