    for field in ('production_definition', 'production_binding', 'admission'):
        if previous[field] != row[field]:
            raise ValueError(f'STARTING_LOADOUT_IDENTITY_CONFLICT:{key}:{field}')
    for group, fact in row['semantics'].items():
        # The canonical owner's presentation retains its exact text. Source
        # descriptions can differ in punctuation; mechanics never get this rule.
        old = previous['semantics'].get(group, {'state': 'UNKNOWN'})
        if group == 'presentation' and old.get('state') != 'UNKNOWN':
            continue
